#[derive(Clone, Debug, PartialEq)]
pub struct SlotReport {
	pub slot: u8,
	pub present: bool,
	pub card_generation: u64,
	pub atr: Vec<u8>,
	pub powered: bool,
}

impl SlotReport {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<SlotReport> {
		let mut r = Reader::new(bytes);
		let value = SlotReport::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<SlotReport> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = SlotReport::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		w.u8(self.slot)?;
		w.boolean(self.present)?;
		w.u64(self.card_generation)?;
		if self.atr.len() > u16::MAX as usize {
			return None;
		}
		w.u16(self.atr.len() as u16)?;
		for v40 in self.atr.iter() {
			w.u8(*v40)?;
		}
		w.boolean(self.powered)?;
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<SlotReport> {
		let slot = r.u8()?;
		let present = r.boolean()?;
		let card_generation = r.u64()?;
		let atr = {
			let v41 = r.u16()? as usize;
			let v41 = (v41 <= 33).then_some(v41)?;
			let mut v42 = Vec::new();
			v42.try_reserve_exact(v41).ok()?;
			for _ in 0..v41 {
				v42.push(r.u8()?);
			}
			v42
		};
		let powered = r.boolean()?;
		Some(SlotReport { slot, present, card_generation, atr, powered })
	}
}

